import json, pathlib, re, math

nb_path = pathlib.Path("GILT_Artifacts/GILT_Artifacts-main/study/analysis.ipynb")
nb = json.loads(nb_path.read_text())

def find_models():
    models = {
        "Prompt": {"marker": "glm(query_total ~"},
        "Followup": {"marker": "glm(Query_followup~"},
        "All": {"marker": "glm(usage_total ~"},
    }
    cells = nb["cells"]
    for i, cell in enumerate(cells):
        if cell.get("cell_type") != "code":
            continue
        src = "".join(cell.get("source", []))
        for name, m in models.items():
            if m["marker"] in src:
                m["cell_index"] = i
    return models

def parse_coeffs_from_output(text):
    lines = text.splitlines()
    in_coef = False
    coefs = {}
    for line in lines:
        if "Coefficients:" in line:
            in_coef = True
            continue
        if not in_coef:
            continue
        if not line.strip():
            break
        if line.lstrip().startswith(("(", "AI_experience", "info_style", "learning_style")):
            parts = line.split()
            var = parts[0]
            est = float(parts[1])
            se = float(parts[2])
            coefs[var] = (est, se)
    return coefs

def parse_rsq_from_cell(cell):
    vals = []
    for out in cell.get("outputs", []):
        data = out.get("data", {})
        txt = None
        if "text/plain" in data:
            t = data["text/plain"]
            txt = "\n".join(t) if isinstance(t, list) else str(t)
        if not txt:
            continue
        for line in txt.splitlines():
            line = line.strip()
            m = re.match(r"\[1\]\s+([0-9.]+)", line)
            if m:
                vals.append(float(m.group(1)))
    return vals[:2]

models = find_models()
cells = nb["cells"]

for name, m in models.items():
    ci = m["cell_index"]
    out_cell = cells[ci]
    txt = ""
    for out in out_cell.get("outputs", []):
        data = out.get("data", {})
        if "text/plain" in data:
            t = data["text/plain"]
            txt = "\n".join(t) if isinstance(t, list) else str(t)
            break
    coefs = parse_coeffs_from_output(txt)
    rsq_cell = cells[ci+1]
    r2, r2adj = parse_rsq_from_cell(rsq_cell)
    print("MODEL", name)
    for key in ["(Intercept)", "AI_experience", "info_style", "learning_style"]:
        est, se = coefs[key]
        print(" ", key, est, se)
    print("  R2", r2, "Adj", r2adj)
    print()
